    "content": "国庆假期进入第六天，全国多地陆续迎来集中返程车流，主要高速公路、国省道干线车流量高位运行。各地公安交管部门针对交通流量变化和假期返程特点，调整警力部署，加强疏导管控，持续严查严管交通违法，全力为人民群众安全返程创造良好的道路交通环境。截至18时，全国道路交通安全形势总体平稳有序。"
