    "content": "chwt163: 通常是在内核和显卡驱动更新之后 nvidia显卡驱动吗？ 你要知道，安装软件不全是把软件包解压了、文件放好就完事了的。Linux内核更新需要更新/boot下的内核、重新生成initramfs。-dkms内核模块更新需要当场编译内核模块。这些都不算在「净更新大小」里的。 另外文件系统用于维护自身的元数据也不算在里边。 如果是btrfs，你可以更新前后打个只读快照，然后通过 sudo btrfs send --no-data -p 更新前的快照 更新后的快照 | sudo btrfs receive …"
