    "content": "新华社南宁10月6日电（记者林凡诗）记者从中国铁路南宁局集团获悉，截至10月6日，2026年西部陆海新通道铁海联运班列集装箱运输量已突破100万标箱，通道保通保畅能力持续增强，为西南地区外贸经济平稳发展、畅通国内国际双循环提供有力运力支撑。 今年以来，西部陆海新通道双向货流需求持续旺盛。数据显示，今年截至目前，重庆发往钦州港下水货物班列达12万标箱，同比增长31.7%，汽车配件、工程机械、轮胎等工业产品外运量大幅攀升，增幅达95%；钦州港上水发往重庆方向的工业原料班列运输5.3万标箱，同比增长28.7%，其中石英砂…"
