    "pub_date": "2026-10-06 19:35:23",
    "author": "张睿",
    "description": "始建于公元366年的敦煌莫高窟，现存洞窟735个，被联合国教科文组织称为全球现存规模最大、连续修建时间最长、内容最丰富的佛教艺术地。 今年六十多岁的樊再轩，是敦煌研究院研究馆员，也是文物保护修复专家。历经千年的敦煌莫高窟，是他半生守护的地方；千年壁画的方寸之间，更是他守护的文明根脉。 作者：张睿、刘厦、王小骥、东子寒 新华社音视频部制作",
    "content": "始建于公元366年的敦煌莫高窟，现存洞窟735个，被联合国教科文组织称为全球现存规模最大、连续修建时间最长、内容最丰富的佛教艺术地。 今年六十多岁的樊再轩，是敦煌研究院研究馆员，也是文物保护修复专家。历经千年的敦煌莫高窟，是他半生守护的地方；千年壁画的方寸之间，更是他守护的文明根脉。 作者：张睿、刘厦、王小骥、东子寒 新华社音视频部制作"
