    "content": "新华社金边10月6日电（记者吴长伟）由中国路桥工程有限责任公司承建的柬埔寨10号公路（1551号公路）项目近日在菩萨省举行竣工通车典礼。柬埔寨首相洪玛奈、中国驻柬埔寨大使馆临时代办姜楠出席并致辞，政府官员、项目参建人员及当地民众代表共约3000人参加典礼。 洪玛奈感谢中方支持建设10号公路且始终支持柬埔寨各领域发展，特别是帮助柬埔寨建设了众多交通基础设施。他表示，10号公路将便利群众出行，更将便利马德望省、菩萨省农产品及其他各类货物运往戈公省的港口和西哈努克省的深水港。此外，这条穿行于豆蔻山脉茂密森林之中的国道，还…"
