    "description": "景德镇迎来“手工瓷业遗存”列入《世界遗产名录》后的首个国庆假期，八方游客纷至沓来。 有人奔着名瓷而来，有人在展柜前追问一件瓷器的诞生，也有人走进遗址，试着回眸窑火照亮过的漫长岁月。 当人们的目光，从瓷器转向制瓷匠人、窑炉与手艺，景德镇在这个假期，续写着属于它的故事。 记者：阮帅 彭菁 余刚 新华社音视频部制作",
    "content": "景德镇迎来“手工瓷业遗存”列入《世界遗产名录》后的首个国庆假期，八方游客纷至沓来。 有人奔着名瓷而来，有人在展柜前追问一件瓷器的诞生，也有人走进遗址，试着回眸窑火照亮过的漫长岁月。 当人们的目光，从瓷器转向制瓷匠人、窑炉与手艺，景德镇在这个假期，续写着属于它的故事。 记者：阮帅 彭菁 余刚 新华社音视频部制作"
