    "title": "点头、抢话、会脸红 一半人分辨不出这 是位AI 小姐姐",
    "link": "https://news.mydrivers.com/1/1155/1155534.htm",
    "pub_date": "2026-10-06 18:41:38",
    "author": "",
    "description": "",
    "content": "一个男人对着镜头拧魔方，屏幕里的女孩盯着他手上的动作，时不时点头，提醒他下一步该转哪一面。他卡住了，低头琢磨，她没有插话，只是安静地等着。等他重新动手，她才接上一句。 如果没人告诉你，这看起来就是一次再普通不过的视频通话。 但屏幕里那个女孩并不存在。 她的脸、她的声音、她的每一次点头和停顿，全部由 AI 实时生成 。 10 月 1 日， 美国 AI 视频公司 Tavus 发布了一个名为 Griffin 的模型 ，并把它定义为全球第一个「人类交互模型」（Human Interaction Model，简称 HIM）。…"
