    "description": "",
    "content": "这个国庆假期，AI短（漫）剧成了旅途中最常见的“电子榨菜”。 从高铁车厢到出租车后座，竖屏AI短剧和漫剧填满了人们的碎片时间。而就在同一技术路径的另一端，国内首部AI超写实院线电影《三星堆：未来往事》定档10月23日登陆全国院线。 从手机小屏到影院巨幕，从“刷着解闷”到“买票进场”。但当制作成本持续下跌、内容供给以每天上千部的速度膨胀，这个行业真正缺的，还是好故事。 ▎从刷着解闷到买票进场，AI内容正走向大银幕 10月2日，在上海开往湖南的高铁上，《科创板日报》记者注意到，所在车厢不少屏幕亮着竖屏画面，画面里是各种…"
