    "content": "新华社利雅得10月6日电（记者罗晨）沙特阿拉伯民航总局6日发表声明说，位于该国南部的两座机场5日晚遭到袭击，导致3人受伤。 声明说，遭袭的两座机场分别为阿卜杜拉·本·阿卜杜勒阿齐兹国王国际机场和奈季兰国际机场。伤者已被送往医院接受治疗。 声明还说，沙特民航总局正协调相关部门评估损失、检查设施安全，并采取必要措施，保障旅客及民航运行安全。"
