    "description": "韩国总统李在明6日说，近期针对韩国银行的部分网络攻击疑有人工智能（AI）参与，要求相关部门尽快查明情况，并制定适应AI时代的网络安全防御措施。 综合法新社和韩联社报道，李在明星期二（10月6日）在内阁会议上说：“一些黑客攻击事件出现了使用AI的迹象，引起民众相当大的担忧和不安。”他要求有关部门迅速、明确地查明攻击情况，并集中人员和资源，将损失降至最低。 韩国警方已就多家商业银行遭网络攻击、导致客户个人资料外泄一事展开全面调查，并成立28…",
    "content": "韩国总统李在明6日说，近期针对韩国银行的部分网络攻击疑有人工智能（AI）参与，要求相关部门尽快查明情况，并制定适应AI时代的网络安全防御措施。 综合法新社和韩联社报道，李在明星期二（10月6日）在内阁会议上说：“一些黑客攻击事件出现了使用AI的迹象，引起民众相当大的担忧和不安。”他要求有关部门迅速、明确地查明攻击情况，并集中人员和资源，将损失降至最低。 韩国警方已就多家商业银行遭网络攻击、导致客户个人资料外泄一事展开全面调查，并成立28人规模的专项调查组‌负责侦办‌。 韩国金融委员会上星期五（2日）说，韩国新韩银行…"
