    "description": "新华社伊斯坦布尔10月6日电 土耳其伊斯坦布尔一所中学6日上午发生持刀行凶事件，造成8人受伤。 土耳其卫生部长凯末尔·梅米什奥卢当天在社交媒体上说，8名伤者正在医院接受治疗，其中1人情况危重。 据土耳其媒体报道，6日8时40分许，一名15岁女生在伊斯坦布尔一所中学内持刀袭击学生，目前已被警方控制。事件具体经过及动机仍在调查中。",
    "content": "新华社伊斯坦布尔10月6日电 土耳其伊斯坦布尔一所中学6日上午发生持刀行凶事件，造成8人受伤。 土耳其卫生部长凯末尔·梅米什奥卢当天在社交媒体上说，8名伤者正在医院接受治疗，其中1人情况危重。 据土耳其媒体报道，6日8时40分许，一名15岁女生在伊斯坦布尔一所中学内持刀袭击学生，目前已被警方控制。事件具体经过及动机仍在调查中。"
