    "content": "新华社北京10月6日电 题：影视剧出海，让世界感悟中国人的生活哲学 新华社记者叶书宏 近期，多部中国影视作品陆续在海外上映。电影《欢迎来龙餐馆》在马来西亚、新加坡等地院线上映，把“好好吃饭”的故事讲给世界；电影《给阿嬷的情书》登陆泰国、英国、澳大利亚等多地，所到之处引发观众情感共鸣；都市剧《早春晴朗》上线流媒体平台奈飞，开播两日即冲入54个国家和地区的剧集日榜前十，更在巴西创下国产剧首次登顶当地日榜的纪录。这些作品尝试以可共情的日常经验与世界对话，全景式展开当代中国人的精神图谱与生活本真。 《给阿嬷的情书》里，泛黄…"
