    "title": "国庆游上海 人们还是喜欢这些老味道",
    "link": "http://www.news.cn/20261006/6808024449074584840da22352709279/c.html",
    "pub_date": "2026-10-06 16:10:26",
    "author": "刘颖",
    "description": "老字号是时光沉淀的城市符号 也是岁月镌刻的城市记忆 在上海南京路、豫园等地 老字号成为假期游客们 品尝上海味道 购买伴手礼的好选择 2026年10月2日，游人行走在上海南京东路步行街。新华社记者 刘颖 摄 上海是全国拥有 “中华老字号”最多的城市 从泛黄档案里近代民族工商业的星火 到货架上琳琅满目的创新产品 百年国货在文旅热潮中 焕发全新活力 大白兔奶糖 一颗奶糖 甜了几代中国人的童年 “大白兔”奶糖的前身 可追溯至1943年的“ABC…",
