    "content": "世界银行6日发布东亚和太平洋地区经济预测更新报告，将2026年该地区经济增速预测上调至4.5%，较4月预测高0.3个百分点。 报告表示，这一经济增速上调很大程度上是由于作为人工智能价值链一部分的国家高技术投资和出口表现强劲。在市场力量、可再生能源使用增加、动用库存和消费者补贴等因素共同作用下，高能源价格的拖累没有预期那样严重。 世界银行表示，在高技术产品制造和出口推动下，该地区多个经济体今年经济增速超出此前预期。其中，越南、马来西亚和泰国今年经济增速预测被分别上调1.1个百分点、0.7个百分点和0.7个百分点。对高…"
