    "author": "卢丹阳,王思俊",
    "description": "位于喜马拉雅山脉南麓的勒布沟，藏语意为“好地方”。这里是西藏自治区山南市错那市的一处边境沟谷，也是我国少数民族——门巴族的主要聚居地之一。路旁，娘江曲奔流而下，串起吉巴、贡日、麻麻、勒四个门巴民族乡。 8月1日，西藏自治区山南市错那市的勒布沟云雾缭绕。新华社记者卢丹阳 摄 处于勒布沟深处的勒门巴民族乡平均海拔2300多米，气候温暖湿润，终年云雾缭绕。在勒乡，旦增加措、次仁石达、多吉旦增三兄弟陆续参军，退役后又相继回到家乡，参与家乡建设，…",
    "content": "位于喜马拉雅山脉南麓的勒布沟，藏语意为“好地方”。这里是西藏自治区山南市错那市的一处边境沟谷，也是我国少数民族——门巴族的主要聚居地之一。路旁，娘江曲奔流而下，串起吉巴、贡日、麻麻、勒四个门巴民族乡。 8月1日，西藏自治区山南市错那市的勒布沟云雾缭绕。新华社记者卢丹阳 摄 处于勒布沟深处的勒门巴民族乡平均海拔2300多米，气候温暖湿润，终年云雾缭绕。在勒乡，旦增加措、次仁石达、多吉旦增三兄弟陆续参军，退役后又相继回到家乡，参与家乡建设，守护着这片土地。 走进勒乡，一栋栋富有门巴民族风情的小楼在路旁整齐排列。过去这里…"
