    "title": "天工开物城 钢城“锂想”地——江西新余高质量发展走笔",
    "link": "http://www.news.cn/20261006/44f77d364bb94c7bb60751d88d3318f9/c.html",
    "pub_date": "2026-10-06 14:27:36",
    "author": "",
    "description": "跨越近400年时光，一本古籍与一座城市，在岁月长河中展开了耐人寻味的对话。 在江西省新余市，明代科学家宋应星写下《天工开物》。这部被誉为“中国17世纪工艺百科全书”的科技巨著，凝结着“天人合一、精工造物、经世致用、实干兴邦”的中华匠心。 文脉赓续，实干不息。连续四年跻身全国城市创新能力百强，今年上半年规上工业增加值增长8.8%、增幅全省第一——这座因钢设市、因工立市的城市，正赓续天工精神转型突围，以“新”的闯劲、“钢”的韧性、“锂”的活…",
