    "content": "新华社突尼斯10月6日电（记者周昊瑾）阿尔及尔消息：阿尔及利亚《独立青年报》网站5日发表题为《新中国成立77周年，回望阿中两国深厚友谊》的文章。文章指出，新中国成立77年来取得一系列伟大成就，并同包括阿尔及利亚在内的发展中国家形成紧密的伙伴关系。文章摘要如下： 77年来，中国历经改革开放、加入世贸组织等诸多重要事件，逐渐从积贫积弱的国家蜕变为全球重要力量。同时，中国的发展轨迹始终与广大发展中国家，特别是非洲国家的发展命运紧密联结，非中合作论坛等机制为构建新时代全天候非中命运共同体持续注入力量，助力非中团结合作，实现…"
